#include <bits/stdc++.h>
using namespace std;

int choose_two(int n) {
    if (n < 2) return 0;
    return n * (n - 1) / 2;
}

int choose_three(int n) {
    if (n < 3) return 0;
    return n * (n - 1) * (n - 2) / 6;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    double p;
    cin >> n >> p;
    int total = choose_three(n);
    for (int i = 0; i <= n; i++) {
        double prob = 0;
        double p1 = (double)i * choose_two(n - i) / total;
        double p2 = (double)choose_two(i) * (n - i) / total;
        double p3 = (double)choose_three(i) / total;
        prob = p1 / 2 + p2 + p3;
        if (prob >= p) {
            cout << i << "\n";
            break;
        }
    }
    return 0;
}
